   "orig": "At #MoveCebu forum, Cebuanos define what a liveable city should be",
   "lead": "Nel corso del forum #MoveCebu, la comunità locale ha discusso e stabilito quali caratteristiche debba possedere un centro urbano per poter essere considerato vivibile. Tra le voci intervenute, la leader di una comunità economicamente svantaggiata, Lourdes Bueza, ha sottolineato che una città a misura d'uomo deve garantire che nessuno venga lasciato indietro. Lo riferisce Rappler.",
