   "orig": "Roma, ludoteche a tempo per il sabato sera: così le strutture accoglieranno i piccoli per lasciare qualche ora di libertà ai genitori",
   "lead": "Nei quartieri romani, a partire dalla Garbatella, vengono introdotte ludoteche aperte a tempo in occasione del sabato sera, con l'obiettivo di accogliere i bambini e offrire alle famiglie qualche ora di tempo libero. L'iniziativa unisce l'esigenza di spazi ricreativi per i più piccoli alla conquista di momenti di svago per i genitori. Lo riferisce Il Messaggero – Roma.",
