   "lead": "La nazionale australiana di rugby dei Wallabies dovrà fare a meno di Ben Donaldson in vista del secondo e decisivo test della Bledisloe Cup in programma a Sydney, operando diverse modifiche nella formazione. Il commissario tecnico Les Kiss ha scelto di affidare la maglia numero 10 a Declan Meredith, inserendo il giovane esordiente Harry McLaughlin-Phillips come alternativa in panchina. Lo riferisce ABC News Australia.",
