   "orig": "Kyrgyzstan's economy projected to grow by 8.8% in 2026, among highest rates in Asia",
   "lead": "L'economia del Kirghizistan registrerà una crescita stimata all'8,8 per cento nel corso del 2026, superando i ritmi di Uzbekistan, India, Cina e di altre nazioni asiatiche. Questa espansione contrasta con il rallentamento della crescita globale prevista al 2,6 per cento, frenata da tensioni geopolitiche, restrizioni commerciali e aumento dei costi di indebitamento. Lo riferisce Daryo.",
