   "orig": "Fires Arrive in the Amazon Rainforest",
   "lead": "In concomitanza con il fenomeno climatico di El Niño, una serie di incendi boschivi attraversa le regioni tropicali, partendo dall'Asia equatoriale per estendersi successivamente fino alle aree centrali e orientali della foresta amazzonica. Lo riferisce Nasa.",
