   "sez": "mondo",
   "titolo": "Migrazioni e tensioni politiche tra Spagna e Uruguay",
   "orig": "El obispo responsable de la comisión episcopal de migraciones: “Hay mucho miedo, mucha ideología, mucha ‘fake news”",
   "lead": "Fernando García Cadiñanos, vescovo e responsabile della commissione migrazioni in Spagna, ha denunciato il clima di paura e le fake news che circondano il tema dei migranti, criticando aspramente l'attuale sistema economico per le sofferenze che causa. Parallelamente, in Uruguay, si è acceso un durissimo scontro politico al Senato: il legislatore Nicolás Viera ha accusato il presidente Luis Lacalle Pou di essere il responsabile politico di presunte frodi amministrative legate al caso Cardama, scatenando la reazione immediata del Partito Nazionale che ha respinto le accuse come strumentali.",
   "more": [
    "Le questioni migratorie in Spagna e le dispute politiche in Uruguay rappresentano sfide cruciali per la stabilità democratica e sociale dei due paesi. Mentre in Europa il dibattito si concentra sull'accoglienza e l'etica, in America Latina la trasparenza amministrativa e la responsabilità dei vertici dello Stato sono temi caldi che influenzano l'opinione pubblica."
   ],
