   "id": "z1cb180fa",
   "sez": "salute",
   "titolo": "Studio sull'accuratezza della segnalazione degli eventi avversi alla FDA",
   "orig": "Evaluation of the accuracy, completeness, and compliance of current summary reporting of adverse events to the Food and Drug Administration using the manufacturer and user facility device experience (MAUDE) database: cross sectional study",
   "lead": "Uno studio trasversale ha analizzato la completezza e la conformità delle segnalazioni di eventi avversi relativi ai dispositivi medici archiviate nel database MAUDE della Food and Drug Administration (FDA) tra luglio 2019 e giugno 2025. La ricerca ha esaminato 6308 rapporti riassuntivi, verificando l'accuratezza dei codici dei problemi, la coerenza tra i dati numerici e le descrizioni narrative e il rispetto delle scadenze previste. I risultati evidenziano criticità nella conformità dei produttori ai requisiti normativi richiesti dall'agenzia statunitense. Lo riferisce The BMJ.",
   "more": [
    "Il database MAUDE (Manufacturer and User Facility Device Experience) è uno strumento fondamentale utilizzato dalla FDA per monitorare la sicurezza dei dispositivi medici dopo la loro immissione sul mercato. La segnalazione degli eventi avversi è obbligatoria per legge e serve a identificare tempestivamente rischi potenziali per la salute dei pazienti."
   ],
