   "id": "z4057f23c",
   "sez": "ingegneria",
   "titolo": "Riqualificazione urbana a Jingdezhen: nasce la Zhuozhuo Community",
   "orig": "Zhuozhuo Community / WEI+ Design",
   "lead": "Nel cuore dello storico distretto di Taoyangli a Jingdezhen, lo studio WEI+ Design ha completato il progetto di rigenerazione urbana Zhuozhuo Community. L'intervento ha trasformato un insieme di edifici preesistenti, strutture residenziali e vicoli tradizionali in una comunità culturale multifunzionale. Situata tra una via commerciale di 600 anni e il sito archeologico del Forno Imperiale, l'area conserva la complessa struttura urbana legata alla secolare produzione di ceramica, integrando architettura storica e nuove funzioni sociali in un ambiente denso e stratificato. Lo riferisce ArchDaily.",
   "more": [
    "Jingdezhen è storicamente conosciuta come la \"capitale della porcellana\" della Cina. I progetti di rigenerazione urbana in queste aree mirano a preservare il patrimonio storico e artigianale, come gli antichi vicoli e i laboratori, adattandoli però alle esigenze abitative e turistiche moderne senza cancellare l'identità del luogo."
   ],
