   "id": "z0aed70f8",
   "sez": "salute",
   "titolo": "Allarme nel Regno Unito per l'aumento delle prescrizioni di testosterone",
   "orig": "Implications of commercial testosterone prescribing for the NHS",
   "lead": "Nel Regno Unito si registra una rapida crescita delle prescrizioni di testosterone nell'ambito del Servizio Sanitario Nazionale (NHS), con un aumento del 52% tra il 2020 e il 2025. Gli esperti avvertono che il trattamento si sta estendendo dai casi di ipogonadismo accertato a persone con sintomi generici, per le quali i benefici e i rischi a lungo termine non sono ancora chiari. Il mercato del testosterone, valutato 205 milioni di dollari nel 2024, è destinato a raddoppiare entro il 2032, coinvolgendo anche un numero crescente di donne sopra i 50 anni. Lo riferisce The BMJ.",
   "more": [
    "Il testosterone è un ormone fondamentale, ma la sua integrazione farmacologica deve essere attentamente monitorata. L'uso improprio o eccessivo può comportare rischi cardiovascolari e metabolici. L'espansione commerciale del settore solleva dubbi sulla medicalizzazione di sintomi comuni legati all'invecchiamento che potrebbero non richiedere una terapia ormonale sostitutiva."
   ],
