   "sez": "viaggi",
   "titolo": "Hong Kong: oltre 200 infrazioni per i tassisti col nuovo sistema a punti",
   "orig": "Hong Kong logs 229 taxi driver offences under points system, over half involving refusal of hire",
   "lead": "Dall'entrata in vigore del sistema di demerito a punti nel 2024, Hong Kong ha registrato 229 infrazioni da parte dei conducenti di taxi. Secondo i dati forniti dal Segretario per i Trasporti Mable Chan, oltre la metà dei casi riguarda il rifiuto di fornire il servizio ai clienti. Il sistema mira a migliorare la qualità del trasporto pubblico e la condotta dei guidatori in una delle città più trafficate al mondo. Le autorità monitorano costantemente l'efficacia della misura per garantire un servizio affidabile a residenti e turisti. Lo riferisce Hong Kong Free Press.",
   "more": [
    "Il sistema a punti per i conducenti professionisti è un metodo di regolamentazione che prevede sanzioni amministrative e la sospensione della licenza al raggiungimento di una determinata soglia di infrazioni. A Hong Kong, il rifiuto di imbarcare passeggeri è considerato una violazione grave che danneggia l'efficienza della mobilità urbana."
   ],
