   "titolo": "Un nuovo romanzo ripercorre la storia di Ruth Ellis",
   "orig": "BOOK EXCERPT: A Fatal Love — Reimagining the story of the last woman executed in Britain",
   "lead": "La scrittrice Louisa Treger ha pubblicato \"A Fatal Love\", un romanzo di narrativa storica che reimmagina la tragica vita di Ruth Ellis, l'ultima donna a essere stata giustiziata nel Regno Unito. La pubblicazione del libro giunge in un momento di rinnovato interesse per il caso, a seguito della grazia postuma concessa a Ellis nel luglio 2026. L'opera si propone di dare una nuova prospettiva sulla figura della protagonista, esplorando il contesto sociale e le vicende personali che portarono alla sua condanna a morte. Lo riferisce Daily Maverick.",
