   "id": "z17ddfa1a",
   "sez": "cucina",
   "titolo": "Spaghetti alla Marmite: la ricetta rapida di Rachel Roddy",
   "orig": "Rachel Roddy’s recipe for spaghetti with Marmite | A kitchen in Rome",
   "lead": "La cuoca Rachel Roddy ha proposto una variante rapida degli spaghetti utilizzando la Marmite per creare un piatto ricco di umami. La preparazione, ispirata a una ricetta italiana per gli spaghetti con estratto di carne, prevede di bollire la pasta, condirla con burro e parmigiano, e infine aggiungere un cucchiaio di estratto di carne (o Marmite) sciolto in poca acqua calda. Questa soluzione pratica è pensata per chi ha poco tempo ma non vuole rinunciare a un sapore intenso, trasformando ingredienti semplici in un pasto sorprendente. Lo riferisce The Guardian – Cucina.",
   "more": [
    "L'umami è considerato il quinto gusto fondamentale e si trova in ingredienti come il pomodoro, il parmigiano e gli estratti di lievito o carne. La Marmite, spalmabile britannica a base di estratto di lievito, è nota per il suo sapore estremamente forte e salato, capace di agire come un potente esaltatore di sapidità in cucina."
   ],
