   "orig": "Musk says US government may be behind slowdown of Ukraine drone speeds",
   "lead": "Dalla notte di martedì i terminali Starlink in dotazione ai militari ucraini hanno smesso di funzionare oltre i 160 km/h, senza spiegazioni ufficiali: una limitazione che rischia di far perdere centinaia di missioni di drone, comprese quelle a lungo raggio contro le raffinerie russe. Elon Musk ha suggerito che dietro il rallentamento potrebbe esserci il governo americano. Zelensky, intervistato a Londra, ha detto di sentirsi personalmente «tradito» da Trump e ha annunciato la ripresa degli attacchi ucraini agli impianti petroliferi russi, sospesi nei giorni scorsi su pressione di Washington.",
